import FeatureSectionV10 from "./components/feature-section-v10"

export default function Page() {
  return (
    <div className="p-4">
      <FeatureSectionV10 />
    </div>
  )
}

import FeatureShowcase from "./feature-showcase"

export default function FeatureSectionV10() {
  return (
    <section className="py-4 md:py-6 lg:py-8">
      <div className="mx-auto max-w-7xl px-4 sm:px-6">
        <FeatureShowcase />
      </div>
    </section>
  )
}

"use client"

import { useState } from "react"

import {
  featureSectionItems,
  featureSectionTitle,
  type FeatureIconId,
} from "../lib/features"
import { useHoverIntent } from "../hooks/use-hover-intent"
import FeatureCard from "./feature-card"
import FeaturePanel from "./feature-panel"

export default function FeatureShowcase() {
  const [activeIcon, setActiveIcon] = useState<FeatureIconId>(
    featureSectionItems[0]?.icon ?? "flow"
  )
  const { schedule, commit } = useHoverIntent(setActiveIcon)

  return (
    <div className="flex flex-col gap-5 lg:gap-6">
      <header className="max-w-2xl">
        <h2 className="m-0 text-2xl font-medium leading-snug tracking-[-0.02em] text-balance sm:text-3xl sm:leading-[1.2] lg:text-[2rem] lg:leading-[1.2]">
          {featureSectionTitle}
        </h2>
      </header>

      <div className="flex flex-col gap-5 lg:grid lg:grid-cols-2 lg:items-stretch lg:gap-8 xl:gap-10">
        <ul className="m-0 flex min-w-0 list-none flex-col gap-2.5 p-0 sm:gap-3">
          {featureSectionItems.map((item) => (
            <li key={item.id} className="m-0 p-0">
              <FeatureCard
                item={item}
                active={activeIcon === item.icon}
                onHoverIntent={() => schedule(item.icon)}
                onActivate={() => commit(item.icon)}
              />
            </li>
          ))}
        </ul>

        <div className="min-w-0 w-full">
          <FeaturePanel activeIcon={activeIcon} />
        </div>
      </div>
    </div>
  )
}

import type { ComponentType } from "react"

import { cn } from "@/lib/utils"

import type { FeatureItem } from "../lib/features"
import { FeatureCardCorners } from "./feature-card-corners"

export default function FeatureCard({
  item,
  active,
  onHoverIntent,
  onActivate,
}: {
  item: FeatureItem
  active: boolean
  /** Debounced hover — used so sweeping cards does not thrash the morph. */
  onHoverIntent: () => void
  /** Immediate commit — focus / click for a11y. */
  onActivate: () => void
}) {
  return (
    <button
      type="button"
      onMouseEnter={onHoverIntent}
      onFocus={onActivate}
      onClick={onActivate}
      className={cn(
        "relative w-full cursor-pointer border border-dashed bg-transparent p-4 text-left motion-safe:transition-colors duration-200 sm:p-5",
        "border-border/80 hover:border-primary/45 focus-visible:border-primary/55 focus-visible:outline-none",
        active && "border-primary/50 bg-primary/3"
      )}
      aria-pressed={active}
    >
      <FeatureCardCorners active={active} />
      <div className="flex flex-col gap-1">
        <h3
          className={cn(
            "m-0 text-[0.9375rem] font-medium leading-snug tracking-[-0.01em] text-foreground sm:text-base",
            active && "text-primary"
          )}
        >
          {item.title}
        </h3>
        <p className="m-0 text-[0.8125rem] leading-relaxed text-muted-foreground sm:text-sm">
          {item.description}
        </p>
      </div>
    </button>
  )
}

